    public static void main(String[] args) {
        // 实例化一个商品类
        ProductStock stack = new ProductStock(new Product());
        // 实例化生产者和消费者任务类
        ProduceRunnable pr = new ProduceRunnable(stack);
        ConsumeRunnable cr = new ConsumeRunnable(stack);
